import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const l=JSON.parse('{"title":"CommentComposer","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/comment-composer.md","filePath":"workbench/comment-composer.md"}'),d={name:"workbench/comment-composer.md"};function n(s,e,c,i,h,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="commentcomposer" tabindex="-1">CommentComposer <a class="header-anchor" href="#commentcomposer" aria-label="Permalink to &quot;CommentComposer&quot;">​</a></h1><p>CommentComposer is where a comment or a reply is written and posted.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it under a thread for a reply, at the foot of a comments panel, or where a new comment is started on the stage. The application posts the text in <code>onpost</code> and decides what a failure means; the composer keeps the text when the post fails. Text that is not posted, such as a note, goes in a <a href="./../components/textarea">Textarea</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>onpost</code></td><td>required</td><td>Called with the trimmed text</td></tr><tr><td><code>placeholder</code></td><td>&quot;Write a comment&quot;</td><td>The placeholder and the accessible name</td></tr><tr><td><code>submitLabel</code></td><td>&quot;Post&quot;</td><td>The text of the button</td></tr><tr><td><code>value</code></td><td><code>&#39;&#39;</code></td><td>The text being written (bindable)</td></tr><tr><td><code>oncancel</code></td><td></td><td>Called with Escape</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Nothing can be written or posted</td></tr><tr><td><code>autofocus</code></td><td><code>false</code></td><td>Takes the focus, with the caret at the end</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is an <a href="./../components/input-group">InputGroup</a>: a <a href="./../components/textarea">Textarea</a> of one line that grows to four and then scrolls, and a primary <a href="./../components/button">Button</a> on its right, which moves under it when the column is narrow. Enter posts and Shift+Enter starts a new line; while a character is being composed (an input method), Enter is the input method&#39;s. Escape calls <code>oncancel</code>. Empty text is not posted and the button is disabled. <code>onpost</code> receives the text trimmed at both ends; when it returns a promise, the composer waits for it, and it clears the text unless the result is <code>false</code>. The messages are <code>writeComment</code> and <code>post</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/comment-composer/" title="CommentComposer" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/comment-composer/" target="_blank" rel="noopener">CommentComposer</a></figcaption></figure>',10)])])}const u=t(d,[["render",n]]);export{l as __pageData,u as default};
